package ru.neverland.townyresearch.licenses;

import java.util.*;import java.util.concurrent.*;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.plugin.Plugin;import org.bukkit.scheduler.BukkitTask;
import com.palmergames.bukkit.towny.*;import com.palmergames.bukkit.towny.object.Town;import com.palmergames.bukkit.towny.object.economy.*;
import ru.neverland.core.*;import ru.neverland.townyresearch.service.ResearchService;
import static ru.neverland.townyresearch.licenses.TechLicense.Phase.*;

/** Finite licensed effect, funded by a real buyer debit and exact seller credit. */
public final class LicenseService {
    private final Plugin plugin;private final ResearchService research;private final LicenseRepository repo;private volatile LicenseSettings settings;private BukkitTask timer;
    private CompletionStage<?> operation=CompletableFuture.completedFuture(null);private CompletionStage<Void> closing;private volatile boolean stopping;private long warned;private UUID invoking;private volatile RawPayment raw;private boolean clockTurn;private final Map<UUID,Integer> windows=new HashMap<>(),usedOffer=new HashMap<>();
    private java.util.function.Function<UUID,Player> players=Bukkit::getPlayer;private Authorization authorization;
    private static final class Authorization{final UUID id;final long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);BukkitTask task;Authorization(UUID id){this.id=id;}}
    private final CompletableFuture<Void> ioClosed=new CompletableFuture<>();
    private final ThreadPoolExecutor io=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(8),r->{var t=new Thread(r,"nlt-research-license-io");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy()){@Override protected void terminated(){ioClosed.complete(null);}};
    private record Outcome(TechLicense.Phase phase,String note){}
    private static final class RawPayment{final CompletableFuture<Outcome> done=new CompletableFuture<>();volatile boolean running;}
    public LicenseService(Plugin plugin,ResearchService research,LicenseRepository repo,LicenseSettings settings){this.plugin=plugin;this.research=research;this.repo=repo;this.settings=settings;}
    public void start(){timer=SuiteScheduler.get().runTaskTimer(plugin,()->pulse(1),20,20);}
    public void reload(LicenseSettings next){try(var g=SuiteState.guard()){settings=next;}}
    public boolean available(){return settings.enabled()&&!stopping&&plugin.isEnabled()&&!SuiteState.frozen(plugin.getName())&&repo.writable();}
    public boolean busy(){return repo.busy()||!operation.toCompletableFuture().isDone();}
    public List<TechLicense> all(){return List.copyOf(repo.rows().values());}
    public TechLicense get(UUID id){return repo.rows().get(id);}
    public String availability(){return !settings.enabled()?"Технологические лицензии приостановлены":!repo.writable()?"Журнал лицензий требует проверки":!treasury().ready()?"Ожидается подтверждаемая казна TreasuryPlus":"Лицензии доступны";}
    private void ready(){if(!available())throw new IllegalStateException(availability());if(busy())throw new IllegalStateException("Лицензия сохраняется; обновите меню через секунду");}
    public String paymentNotice(TechLicense row){try(var guard=SuiteState.guard()){if(row.phase()!=ACCEPTING&&row.phase()!=FUNDING&&row.phase()!=REFUNDING)return "";var api=treasury();if(!api.ready())return "Ожидается доступ к подтверждаемой городской казне";UUID id=row.terms().operation(row.phase()==REFUNDING?"refund":"debit");try{String state=String.valueOf(status(api,id).get("status"));return switch(state){case "REVIEW"->"Администратору нужно сверить казну: "+id;case "ABSENT"->"Казна ещё не приняла запрос: ждём свободного бюджета";case "PREPARED","INVOKING"->"Резерв сохранён; ждём подтверждения банка";case "REJECTED"->"Банк не выполнял перевод; ожидается обработка квитанции";default->"Казна подтвердила перевод; завершаем запись лицензии";};}catch(Exception e){return "Состояние казны временно недоступно; повторной выплаты нет";}}}
    private void manager(Player player,UUID town){Town t=TownyAPI.getInstance().getTown(town);if(t==null||!player.hasPermission("neverlandtownyresearch.use")||!player.hasPermission("neverlandtownyresearch.licenses")||!research.manager(player,t))throw new IllegalArgumentException("Подтвердить условия может управляющий своего города");}
    private ApiServices.Connection treasury(){return ApiServices.connect("NeverLandTownyTreasuryPlus","ru.neverland.townytreasury.api.TownyTreasuryApi",1,"requestDebit","debitStatus","requestRefund","refundStatus");}
    public CompletionStage<TechLicense> offer(Player player,UUID buyer,String technology,int level,long cents,int hours){try(var g=SuiteState.guard()){
        ready();Town seller=research.town(player);if(seller==null)throw new IllegalArgumentException("Сначала вступите в город");manager(player,seller.getUUID());if(TownyAPI.getInstance().getTown(buyer)==null)throw new IllegalArgumentException("Город-покупатель не найден");if(!treasury().ready())throw new IllegalStateException("Для лицензий нужна доступная казна TreasuryPlus с подтверждением платежей");
        var tech=research.settings().technologies().get(technology);if(tech==null||!tech.enabled()||level<1||level>tech.levels().size()||research.level(seller.getUUID(),technology)<level)throw new IllegalArgumentException("Город должен сам изучить выбранный уровень включённой технологии");
        if(hours<1||hours>168)throw new IllegalArgumentException("Срок лицензии: 1..168 часов активной работы");if(repo.rows().size()>=TechLicense.MAX_RECORDS)throw new IllegalStateException("Архив лицензий достиг предела");long pending=repo.rows().values().stream().filter(r->r.phase()==OFFERED&&r.terms().seller().equals(seller.getUUID())).count();if(pending>=settings.maximumOffers())throw new IllegalStateException("Слишком много открытых предложений вашего города");
        var terms=new TechLicense.Terms(UUID.randomUUID(),seller.getUUID(),buyer,player.getUniqueId(),technology,level,tech.levels().get(level-1).bonus(),cents,Math.multiplyExact(hours,3600));var row=TechLicense.offered(terms,settings.offerSeconds(),System.currentTimeMillis()).by(actor(player));return track(save(row));
    }}
    public CompletionStage<TechLicense> accept(Player player,UUID id,long revision){try(var g=SuiteState.guard()){
        ready();var row=exact(id,revision);manager(player,row.terms().buyer());if(row.phase()!=OFFERED||offerRemaining(row)==0)throw new IllegalStateException("Предложение уже обработано или истекло");
        var t=row.terms();var technology=research.settings().technologies().get(t.technology());if(technology==null||!technology.enabled()||TownyAPI.getInstance().getTown(t.seller())==null||research.level(t.seller(),t.technology())<t.level())throw new IllegalStateException("Продавец больше не подтверждает собственную технологию");
        if(research.level(t.buyer(),t.technology())>=t.level())throw new IllegalArgumentException("Ваш город уже изучил этот уровень сам");if(repo.rows().values().stream().anyMatch(r->r.reservesSlot()&&r.terms().buyer().equals(t.buyer())&&r.terms().technology().equals(t.technology())))throw new IllegalStateException("Для этой технологии уже есть лицензия или расчёт");
        return track(save(row.accepted(player.getUniqueId()).by(actor(player))));
    }}
    public CompletionStage<TechLicense> cancel(Player player,UUID id,long revision){try(var g=SuiteState.guard()){
        ready();var row=exact(id,revision);boolean admin=player.isOp()||player.hasPermission("neverlandtownyresearch.admin");var own=research.town(player);if(!admin){if(own==null||!Set.of(row.terms().buyer(),row.terms().seller()).contains(own.getUUID()))throw new IllegalArgumentException("Нет доступа к этой сделке");manager(player,own.getUUID());}
        return switch(row.phase()){case OFFERED->track(save(row.phase(CANCELLED,"Отменено до оплаты").by(actor(player))));case ACCEPTING,FUNDING->track(save(row.cancel("Отмена после проверки расчёта").by(actor(player))));case FUNDED->track(save(row.phase(REFUNDING,"Полный возврат покупателю").by(actor(player))));default->throw new IllegalStateException("После начала выплаты отмена закрыта. Неизвестный результат сначала сверяет администратор.");};
    }}
    public CompletionStage<TechLicense> pause(Player admin,UUID id,long revision){try(var g=SuiteState.guard()){
        if(!admin.isOp()&&!admin.hasPermission("neverlandtownyresearch.admin"))throw new IllegalArgumentException("Нужны права администратора");ready();var row=exact(id,revision);if(row.phase()!=ACTIVE&&row.phase()!=PAUSED)throw new IllegalStateException("Приостановить можно действующую лицензию");return track(save(row.phase(row.phase()==ACTIVE?PAUSED:ACTIVE,"Администратор "+admin.getUniqueId()+": "+(row.phase()==ACTIVE?"пауза без расхода срока":"возобновление срока")).by(actor(admin))));
    }}
    public CompletionStage<TechLicense> resolve(UUID id,boolean paid,org.bukkit.command.CommandSender sender){try(var g=SuiteState.guard()){
        if(!sender.isOp()&&!sender.hasPermission("neverlandtownyresearch.admin"))throw new IllegalArgumentException("Нужны права администратора");if(stopping||busy())throw new IllegalStateException("Лицензии завершают запись");var row=Objects.requireNonNull(get(id),"Лицензия не найдена");if(!row.audited())throw new IllegalStateException("Журнал квитанции ещё сохраняется; повторите сверку позже");if(row.phase()!=PAY_REVIEW)throw new IllegalArgumentException("Нет неопределённой выплаты продавцу по этой лицензии");return track(save((paid?row.paid("Точная сверка: продавец получил оплату"):row.phase(REFUNDING,"Точная сверка: выплаты продавцу не было; полный возврат покупателю")).by(actor(sender))));
    }}
    private LicenseActor actor(org.bukkit.command.CommandSender sender){if(sender instanceof Player player){var town=research.town(player);return LicenseActor.player(player.getUniqueId(),player.getName(),town==null?null:town.getUUID());}return new LicenseActor("SYSTEM","",sender.getName(),"");}
    private TechLicense exact(UUID id,long revision){var row=get(id);if(row!=null&&!row.audited())throw new IllegalStateException("Журнал предыдущего действия сохраняется; обновите меню через несколько секунд");if(row==null||row.revision()!=revision)throw new IllegalStateException("Лицензия изменилась; обновите меню и условия");return row;}
    private CompletionStage<TechLicense> save(TechLicense row){var before=repo.rows();var next=new HashMap<>(before);next.put(row.terms().id(),row);return repo.commit(before,next).thenApply(ack->row);}
    private <T>CompletionStage<T> track(CompletionStage<T> stage){operation=stage;stage.whenComplete((v,e)->{if(e!=null)plugin.getLogger().log(java.util.logging.Level.WARNING,"Лицензия ожидает сохранения или сверки; повторной выплаты нет",e);});return stage;}
    public double bonus(UUID town,String technology){try(var g=SuiteState.guard()){
        if(!available())return 0;var tech=research.settings().technologies().get(technology);if(tech==null||!tech.enabled()||TownyAPI.getInstance().getTown(town)==null)return 0;
        return repo.rows().values().stream().filter(r->r.phase()==ACTIVE&&r.audited()&&windows.getOrDefault(r.terms().id(),0)>0&&r.terms().buyer().equals(town)&&r.terms().technology().equals(technology)).mapToDouble(r->r.terms().bonus()).max().orElse(0);
    }}
    public void pulse(int seconds){try(var g=SuiteState.guard()){
        if(stopping||!repo.writable())return;if(authorization!=null&&System.nanoTime()>=authorization.deadline){if(authorization.task!=null)authorization.task.cancel();authorization=null;}if(available())consumeTime(seconds);if(busy())return;
        for(var row:repo.rows().values())if(row.phase()==PAYING&&!row.terms().id().equals(invoking)){track(save(row.phase(PAY_REVIEW,"Сервер остановился во время выплаты продавцу; проверьте точную квитанцию")));return;}
        if(!available())return;
        clockTurn=!clockTurn;if(clockTurn&&saveClock())return;
        for(var row:repo.rows().values())if(!row.audited()){track(audit(row));return;}
        for(var row:repo.rows().values())if(Set.of(ACCEPTING,FUNDING,FUNDED,REFUNDING).contains(row.phase())){try{if(advancePayment(row))return;}catch(Exception ex){if(System.currentTimeMillis()-warned>=60000){warned=System.currentTimeMillis();plugin.getLogger().warning("Лицензия "+row.terms().id()+" ждёт казну: "+ex.getMessage());}} }
        saveClock();
    }}
    public int remaining(TechLicense row){return Math.addExact(row.remaining(),windows.getOrDefault(row.terms().id(),0));}
    public int offerRemaining(TechLicense row){return Math.max(0,row.offerRemaining()-usedOffer.getOrDefault(row.terms().id(),0));}
    private boolean usable(TechLicense row){var tech=research.settingsSnapshot().technologies().get(row.terms().technology());return tech!=null&&tech.enabled()&&TownyAPI.getInstance().getTown(row.terms().buyer())!=null;}
    private void consumeTime(int seconds){if(seconds<0||seconds>60)throw new IllegalArgumentException("Шаг лицензий: 0..60 секунд");if(seconds==0)return;
        for(var row:repo.rows().values()){UUID id=row.terms().id();if(row.phase()==OFFERED)usedOffer.merge(id,seconds,(a,b)->Math.min(row.offerRemaining(),a+b));else if(row.phase()==ACTIVE&&row.audited()&&usable(row))windows.computeIfPresent(id,(key,value)->Math.max(0,value-seconds));}
    }
    private boolean saveClock(){var before=repo.rows();var next=new HashMap<>(before);var offers=new HashMap<UUID,Integer>();var grants=new HashMap<UUID,Integer>();boolean changed=false;
        for(var row:before.values()){UUID id=row.terms().id();var updated=row;if(row.phase()==OFFERED&&row.audited()){int elapsed=usedOffer.getOrDefault(id,0);updated=row.offerConsumed(elapsed);offers.put(id,elapsed);}else if((row.phase()==ACTIVE||row.phase()==PAUSED)&&row.audited()&&windows.getOrDefault(id,0)==0){if(row.remaining()==0)updated=row.phase(EXPIRED,"Оплаченный срок завершён");else if(row.phase()==ACTIVE&&usable(row)){int n=Math.min(5,row.remaining());updated=row.reserveWindow(n);grants.put(id,n);}}if(updated!=row){next.put(id,updated);changed=true;}}
        if(!changed){windows.keySet().removeIf(id->get(id)==null||get(id).terminal());usedOffer.keySet().removeIf(id->get(id)==null||get(id).phase()!=OFFERED);return false;}
        track(repo.commit(before,next).thenAccept(ack->{try(var g=SuiteState.guard()){grants.forEach(windows::put);offers.forEach((id,n)->usedOffer.computeIfPresent(id,(key,value)->Math.max(0,value-n)));}}));return true;
    }
    /** Unused prepaid time is returned only on graceful shutdown, never guessed after a crash. */
    private CompletionStage<Void> flushRuntime(){try(var g=SuiteState.guard()){if(!repo.writable())return CompletableFuture.completedFuture(null);var before=repo.rows();var next=new HashMap<>(before);for(var row:before.values()){var updated=row;UUID id=row.terms().id();if(row.phase()==ACTIVE||row.phase()==PAUSED)updated=row.returnWindow(windows.getOrDefault(id,0));else if(row.phase()==OFFERED)updated=row.offerConsumed(usedOffer.getOrDefault(id,0));next.put(id,updated);}return repo.commit(before,next).thenAccept(ack->{try(var guard=SuiteState.guard()){windows.clear();usedOffer.clear();}});}}
    @SuppressWarnings("unchecked")private Map<String,Object> status(ApiServices.Connection api,UUID id)throws Exception{return(Map<String,Object>)api.invoke("debitStatus",new Class<?>[]{UUID.class},id);}
    @SuppressWarnings("unchecked")private boolean advancePayment(TechLicense row)throws Exception{
        var api=treasury();if(!api.ready())return false;var t=row.terms();UUID debit=t.operation("debit");
        if(row.phase()==ACCEPTING){var receipt=status(api,debit);if(!Objects.equals(receipt.get("status"),"ABSENT")){requireReceipt(row,receipt,false);track(save(row.phase(FUNDING,"Казна приняла подтверждённые условия")));return true;}if(row.cancelRequested()){track(save(row.phase(CANCELLED,"Отмена до регистрации списания")));return true;}return authorize(row);}
        if(row.phase()==FUNDING){var receipt=status(api,debit);String state=String.valueOf(receipt.get("status"));if(state.equals("ABSENT")){track(save(row.phase(ACCEPTING,"Казна ещё не приняла запрос; полномочия будут проверены повторно")));return true;}
            requireReceipt(row,receipt,false);if(state.equals("PAID")){if(!Boolean.TRUE.equals(receipt.get("backingAvailable")))throw new IllegalStateException("Обеспечение лицензии недоступно");track(save(row.phase(row.cancelRequested()?REFUNDING:FUNDED,"Казна подтвердила обеспеченный платёж")));return true;}if(state.equals("REJECTED")){track(save(row.phase(REJECTED,"Казна подтвердила отсутствие списания; лицензионного бонуса нет")));return true;}return false;}
        var backing=status(api,debit);requireReceipt(row,backing,false);
        if(row.phase()==FUNDED){if(!backing.get("status").equals("PAID")||!Boolean.TRUE.equals(backing.get("backingAvailable")))throw new IllegalStateException("Нет подтверждённого обеспечения");var seller=TownyAPI.getInstance().getTown(t.seller());if(seller==null||!TownyEconomyHandler.isActive()||TownyEconomyHandler.activeAdapter()==null)return false;pay(row);return true;}
        if(row.phase()==REFUNDING){UUID refund=t.operation("refund");var receipt=status(api,refund);String state=String.valueOf(receipt.get("status"));if(state.equals("ABSENT")){if(!backing.get("status").equals("PAID")||!Boolean.TRUE.equals(backing.get("backingAvailable")))throw new IllegalStateException("Обеспечение возврата не подтверждено");var request=(CompletionStage<Map<String,Object>>)api.invoke("requestRefund",new Class<?>[]{UUID.class,UUID.class,UUID.class,String.class,String.class},refund,debit,row.buyerActor(),plugin.getName(),t.refundReason());track(request.handle((v,e)->null));return true;}
            requireReceipt(row,receipt,true);if(state.equals("PAID")){track(save(row.refunded("Подтверждён полный возврат в исходную статью бюджета покупателя")));return true;}return false;
        }return false;
    }
    private boolean authorize(TechLicense row){if(authorization!=null)return false;Player player=players.apply(row.buyerActor());if(player==null)return false;var pending=new Authorization(row.terms().id());authorization=pending;
        try{pending.task=SuiteScheduler.entityLater(plugin,player,()->{if(authorization!=pending)return;authorization=null;if(!available()||busy()||!row.equals(get(pending.id))||!player.isOnline())return;
            try{manager(player,row.terms().buyer());var technology=research.settings().technologies().get(row.terms().technology());if(technology==null||!technology.enabled()||TownyAPI.getInstance().getTown(row.terms().seller())==null||research.level(row.terms().seller(),row.terms().technology())<row.terms().level())throw new IllegalArgumentException("Продавец больше не подтверждает собственную технологию");if(research.level(row.terms().buyer(),row.terms().technology())>=row.terms().level())throw new IllegalArgumentException("Город уже самостоятельно изучил этот уровень");}catch(IllegalArgumentException rejected){track(save(row.phase(REJECTED,"Полномочия или условия изменились до списания: "+rejected.getMessage())));return;}
            try{var api=treasury();if(!api.ready())return;var receipt=status(api,row.terms().operation("debit"));if(!Objects.equals(receipt.get("status"),"ABSENT"))return;var t=row.terms();@SuppressWarnings("unchecked")var request=(CompletionStage<Map<String,Object>>)api.invoke("requestDebit",new Class<?>[]{UUID.class,UUID.class,String.class,String.class,long.class,String.class,UUID.class,String.class},t.operation("debit"),t.buyer(),"infrastructure","research/license",t.cents(),t.debitReason(),row.buyerActor(),plugin.getName());
                track(request.handle((v,error)->error==null).thenCompose(ok->{try(var guard=SuiteState.guard()){if(!ok)return CompletableFuture.completedFuture(null);var current=get(pending.id);if(current==null||current.phase()!=ACCEPTING)return CompletableFuture.completedFuture(null);return save(current.phase(FUNDING,"Казна приняла подтверждённые условия")).thenApply(x->null);}}));
            }catch(Exception wait){/* Busy before intent: retain the same acceptance and operation UUID. */}
        },()->{if(authorization==pending)authorization=null;},1);if(pending.task.isCancelled())authorization=null;return true;}catch(RuntimeException error){authorization=null;return false;}}
    private void requireReceipt(TechLicense row,Map<String,Object> receipt,boolean refund){var t=row.terms();if(!Objects.equals(receipt.get("operation"),t.operation(refund?"refund":"debit").toString())||!Objects.equals(receipt.get("town"),t.buyer().toString())||!Objects.equals(receipt.get("category"),"infrastructure")||!Objects.equals(receipt.get("source"),"research/license")||!(receipt.get("cents") instanceof Number n)||n.longValue()!=t.cents()||!Objects.equals(receipt.get("actor"),row.buyerActor().toString())||!Objects.equals(receipt.get("owner"),plugin.getName())||!Objects.equals(receipt.get("reason"),refund?t.refundReason():t.debitReason())||!Objects.equals(receipt.get("kind"),refund?"REFUND":"DEBIT")||!Objects.equals(receipt.get("backingDebit"),refund?t.operation("debit").toString():""))throw new IllegalStateException("Квитанция казны не совпадает с условиями лицензии");}
    private void pay(TechLicense row){invoking=row.terms().id();var started=row.phase(PAYING,"Ожидается точная квитанция выплаты продавцу");track(save(started).thenCompose(this::bank).thenCompose(result->{try(var g=SuiteState.guard()){var current=get(row.terms().id());return save(result.phase()==ACTIVE?current.paid(result.note()):current.phase(result.phase(),result.note()));}}).whenComplete((v,e)->{try(var g=SuiteState.guard()){invoking=null;}}));}
    private CompletionStage<Outcome> bank(TechLicense row){if(stopping)return CompletableFuture.completedFuture(new Outcome(FUNDED,"Остановка до банковского вызова"));var request=new RawPayment();raw=request;
        try{Bukkit.getGlobalRegionScheduler().run(plugin,task->{if(request.done.isDone())return;request.running=true;Outcome result;if(stopping||!plugin.isEnabled()||SuiteState.frozen(plugin.getName())||!settings.enabled())result=new Outcome(FUNDED,"Пауза до банковского вызова");else try{var seller=TownyAPI.getInstance().getTown(row.terms().seller());var buyer=TownyAPI.getInstance().getTown(row.terms().buyer());if(!usable(row)||seller==null||buyer==null||!TownyEconomyHandler.isActive()||TownyEconomyHandler.activeAdapter()==null)result=new Outcome(FUNDED,"Участник сделки или банк изменился до выплаты; резерв сохранён");else result=credit(row,seller.getAccount());}catch(Throwable error){result=new Outcome(PAY_REVIEW,"Банковский callback не подтвердил выплату: "+error.getClass().getSimpleName());}complete(request,result);});}catch(RuntimeException ex){complete(request,new Outcome(FUNDED,"Планировщик остановлен до банковского вызова"));}return request.done;
    }
    private Outcome credit(TechLicense row,BankAccount account){var t=row.terms();String token="[research-license:"+t.operation("seller")+"]";var proof=new PaymentEvidence(account,true,token,t.cents());var observer=new AccountObserver(){public void withdrew(Account a,double n,String reason){proof.observe(a,false,n,reason);}public void deposited(Account a,double n,String reason){proof.observe(a,true,n,reason);}};
        synchronized(account){try{double current=account.getHoldingBalance(true);if(!Double.isFinite(current)||current>90_000_000_000_000.0-t.cents()/100.0)return new Outcome(FUNDED,"Баланс продавца пока не допускает выплату");}catch(Throwable e){return new Outcome(FUNDED,"Не удалось проверить банк до выплаты");}
            account.addObserver(observer);try{try{account.deposit(t.cents()/100.0,token+" Оплата временной технологии "+t.id());}catch(Throwable error){if(!proof.observed())return new Outcome(PAY_REVIEW,"Нет точной квитанции выплаты продавцу: "+error.getClass().getSimpleName());}return proof.observed()?new Outcome(ACTIVE,"Продавец получил обеспеченную оплату; начался оплаченный срок"):new Outcome(PAY_REVIEW,"Банк не подтвердил точную выплату; автоматического повтора нет");}finally{account.removeObserver(observer);}}
    }
    private void complete(RawPayment request,Outcome result){Runnable action=()->{try(var g=SuiteState.guard()){request.done.complete(result);if(raw==request)raw=null;}};try{io.execute(action);}catch(RejectedExecutionException e){if(!request.done.isDone())CompletableFuture.runAsync(action);}}
    private CompletionStage<Void> audit(TechLicense row){var done=new CompletableFuture<Boolean>();try{io.execute(()->{try{var t=row.terms();boolean payment=row.event()==TechLicense.Event.PAYMENT,refund=row.event()==TechLicense.Event.REFUND;var buyer=new AuditRecord.Party("TOWN",t.buyer().toString(),t.buyer().toString(),t.buyer().toString());var seller=new AuditRecord.Party("TOWN",t.seller().toString(),t.seller().toString(),t.seller().toString());var escrow=new AuditRecord.Party("ESCROW",t.operation("debit").toString(),"Резерв технологической лицензии",t.buyer().toString());done.complete(AuditTrail.record(plugin,new AuditRecord(AuditRecord.id(plugin.getName(),t.id().toString(),row.phase()+":"+row.revision()),row.changedAt(),plugin.getName(),payment?"RESEARCH_LICENSE_PAYMENT":refund?"RESEARCH_LICENSE_REFUND":"RESEARCH_LICENSE",row.phase().name(),t.id().toString(),row.actor().party(),payment||refund?escrow:buyer,refund?buyer:seller,"",0,payment||refund?java.math.BigDecimal.valueOf(t.cents(),2).toPlainString():"","technology="+t.technology()+"; level="+t.level()+"; duration="+t.duration()+"; remaining="+row.remaining()+"; "+row.note())));}catch(Throwable e){done.complete(false);}});}catch(RejectedExecutionException e){done.complete(false);}
        return done.thenCompose(ok->{if(!ok)return CompletableFuture.completedFuture(null);try(var g=SuiteState.guard()){var current=get(row.terms().id());if(!row.equals(current))return CompletableFuture.completedFuture(null);return save(row.auditAck()).thenApply(v->null);}});
    }
    public CompletionStage<Void> stop(){try(var g=SuiteState.guard()){if(closing!=null)return closing;stopping=true;if(timer!=null)timer.cancel();if(authorization!=null){if(authorization.task!=null)authorization.task.cancel();authorization=null;}if(raw!=null&&!raw.running&&!raw.done.isDone())raw.done.complete(new Outcome(FUNDED,"Остановка до банковского вызова"));closing=operation.handle((v,e)->null).thenCompose(v->flushRuntime()).handle((v,e)->e).thenCompose(error->repo.closeAsync().handle((v,e)->error==null?e:error)).thenCompose(error->{io.shutdown();return ioClosed.thenCompose(v->error==null?CompletableFuture.<Void>completedFuture(null):CompletableFuture.<Void>failedFuture(error));});return closing;}}
}
